 367	async fn recover_all_inner(restart~ : Bool = false) -> Unit {
 368	  notify(if restart { "restart" } else { "recover" })
 369	  let base = adapter_state_home() + "/tunnels"
 370	  if !@fs.exists(base) {
 371	    save_diagnostic("recover", "success")
 372	    return
 373	  }
 374	  ignore(saved_proxy_executable())
 375	  let mut failures = 0
 376	  let permits = @async.Semaphore(4)
 377	  @async.with_task_group(async fn(group) {
 378	    for name in @fs.readdir(base, sort=true) {
 379	      let directory = base + "/" + name
 380	      permits.acquire()
 381	      group.spawn_bg(async fn() {
 382	        defer permits.release()
 383	        try {
 384	          if @fs.kind(directory, follow_symlink=false) !=
 385	            @fs.FileKind::Directory ||
 386	            !@fs.exists(directory + "/enabled") {
 387	            return
 388	          }
 389	          let state = @json.parse(
 390	            @fs.read_file(directory + "/state.json").text(),
 391	          )
 392	          validate_state(state)
 393	          set_field(state, "tunnelDirectory", Json::string(directory))
 394	          recover_connection(state, restart~)
