 952	      connection_timeout(started + 60000, async fn() { lifecycle_state(mode) })
 953	    } else {
 954	      lifecycle_state(mode)
 955	    }
 956	    (
 957	      state,
 958	      previous,
 959	      if mode == "recover" || mode == "restart" {
 960	        Some(started + 60000)
 961	      } else {
 962	        None
 963	      },
