1000	          ],
1001	          "workspace-resume",
1002	        ),
1003	      )
1004	      let expires = @env.now() + 60000
1005	      connection_timeout(expires, async fn() {
1006	        let port = if required(state, "connection") == "orca-server" {
1007	          Some(reserve_server_port(state))
1008	        } else {
1009	          None
1010	        }
1011	        ensure_ssh_worker(state, port, deadline=expires)
1012	        codex_addon(state)
1013	        if required(state, "connection") == "orca-server" {
1014	          ignore(recover_server(state))
1015	        }
1016	        emit_connection(state, false, existing=previous, deadline=expires)
1017	      })
1018	    }
1019	    "recover" | "restart" => {
1020	      recover_connection(state, restart=mode == "restart", deadline?)
1021	      let connection = field(previous, "connection").unwrap()
1022	      write_connection(state, connection)
1023	    }
1024	    "suspend" => {
1025	      pause_tunnel(state)
1026	      defer unpause_tunnel(state)
1027	      ignore(
1028	        devsy(
1029	          state,
1030	          ["workspace", "stop", required(state, "workspaceId")],
1031	          "workspace-stop",
1032	        ),
1033	      )
1034	    }
1035	    "destroy" => {
1036	      pause_tunnel(state)
1037	      errdefer unpause_tunnel(state)
1038	      ignore(
1039	        devsy(
