    43	  @fs.mkdir(directory, recursive=true, permission=0o700, allow_exist=true)
    44	  let lock = @fs.open(
    45	    directory + "/launcher.lock",
    46	    mode=ReadWrite,
    47	    create_mode=OpenOrCreate,
    48	    permission=0o600,
    49	  )
    50	  defer lock.close()
    51	  @async.with_timeout(10000, async fn() {
    52	    while !lock.try_lock(Exclusive) {
    53	      @async.sleep(10)
    54	    }
    55	  })
    56	  let target = directory + "/ssh-proxy-adapter"
    57	  let executable = adapter_executable()
    58	  if executable == target {
    59	    return target
    60	  }
    61	  save_diagnostic("ssh-proxy-launcher", "started")
    62	  errdefer save_diagnostic(
    63	    "ssh-proxy-launcher",
    64	    "failed",
    65	    error_type="filesystem",
    66	  )
    67	  let binary = @fs.read_file(executable).binary()
    68	  if !@fs.exists(target) || @fs.read_file(target).binary() != binary {
    69	    // A private executable copy survives package-manager pruning. Rename keeps
    70	    // active proxies valid while create/resume/recover refresh future calls.
    71	    let temporary = directory + "/ssh-proxy-adapter.tmp"
    72	    defer (@fs.remove(temporary) catch { _ => () })
    73	    @fs.write_file(temporary, binary, permission=0o700)
    74	    @fs.rename(temporary, target, replace=true)
    75	  }
    76	  save_diagnostic("ssh-proxy-launcher", "success")
    77	  target
    78	}
