   100	///|
   101	async fn stop_tunnel_master(
   102	  state : Json,
   103	  directory : String,
   104	  verify~ : Bool = false,
   105	) -> Unit {
   106	  @async.with_timeout(2000, async fn() {
   107	    ignore(
   108	      @process.collect_output(
   109	        "ssh",
   110	        ssh_args(state) + ["-S", control_socket(state, directory), "-O", "exit"],
   111	      ),
   112	    )
   113	  }) catch {
   114	    _ => ()
   115	  }
   116	  if verify {
   117	    @async.with_timeout(5000, async fn() {
   118	      while true {
   119	        let (code, _, _) = @process.collect_output(
   120	          "ssh",
   121	          ssh_args(state) +
   122	          [
   123	            "-o",
   124	            "ProxyCommand=false",
   125	            "-S",
   126	            control_socket(state, directory),
   127	            "-O",
   128	            "check",
   129	          ],
   130	        )
   131	        if code != 0 {
   132	          break
   133	        }
   134	        @async.sleep(100)
   135	      }
   136	    })
   137	  }
   138	  if field(state, "socketDirectory") is Some(Json::String(socket_directory)) {
   139	    if @fs.exists(socket_directory + "/socket") {
   140	      @fs.remove(socket_directory + "/socket")
   141	    }
   142	    wait_ssh_proxy(state, "primary")
   143	    let lease = socket_directory + "/primary-proxy.lock"
   144	    if @fs.exists(lease) {
   145	      @fs.remove(lease)
   146	    }
   147	    @fs.rmdir(socket_directory) catch {
   148	      _ => ()
   149	    }
   150	  }
   151	}
