   153	///|
   154	async fn ensure_ssh_worker(
   155	  state : Json,
   156	  port : Int32?,
   157	  deadline? : UInt64,
   158	  restart~ : Bool = false,
   159	) -> Unit {
   160	  let mut expires = deadline.unwrap_or(@env.now() + 60000)
   161	  let base = adapter_state_home() + "/tunnels"
   162	  @fs.mkdir(base, recursive=true, permission=0o700, allow_exist=true)
   163	  let directory = match field(state, "tunnelDirectory") {
   164	    Some(Json::String(old)) if old.has_prefix(base + "/") && @fs.exists(old) =>
   165	      old
   166	    _ => {
   167	      if restart &&
   168	        field(state, "tunnelDirectory") is Some(Json::String(old)) &&
   169	        @fs.exists(old) {
   170	        let lease = @fs.open(
   171	          old + "/startup.lock",
   172	          mode=ReadWrite,
   173	          create_mode=OpenOrCreate,
   174	          permission=0o600,
   175	        )
   176	        defer lease.close()
   177	        @async.with_timeout(30000, async fn() {
   178	          while !lease.try_lock(Exclusive) {
   179	            @async.sleep(100)
   180	          }
   181	        })
   182	        let saved = if @fs.exists(old + "/state.json") {
   183	          @json.parse(@fs.read_file(old + "/state.json").text())
   184	        } else {
   185	          state
   186	        }
   187	        guard field(saved, "workspaceUid") == field(state, "workspaceUid") else {
   188	          raise AdapterError("Tunnel ownership changed")
   189	        }
   190	        restart_tunnel(saved, old)
   191	        expires = @env.now() + 60000
   192	      }
   193	      close_tunnel(state)
   194	      let name = required(state, "workspaceUid")
   195	        .replace_all(old="%", new="%25")
   196	        .replace_all(old="/", new="%2F")
   197	      let directory = base + "/workspace-" + name
   198	      @fs.mkdir(directory, permission=0o700, allow_exist=true)
   199	      set_field(state, "tunnelDirectory", Json::string(directory))
   200	      directory
   201	    }
   202	  }
   203	  let lease = @fs.open(
   204	    directory + "/startup.lock",
   205	    mode=ReadWrite,
   206	    create_mode=OpenOrCreate,
   207	    permission=0o600,
   208	  )
   209	  defer lease.close()
   210	  @async.with_timeout(30000, async fn() {
   211	    while !lease.try_lock(Exclusive) {
   212	      @async.sleep(100)
   213	    }
   214	  })
   215	  if @fs.exists(directory + "/state.json") {
   216	    let saved = @json.parse(@fs.read_file(directory + "/state.json").text())
   217	    guard field(saved, "workspaceUid") == field(state, "workspaceUid") &&
   218	      field(saved, "localPort") ==
   219	      port.map(value => Json::number(value.to_double())) else {
   220	      raise AdapterError("Tunnel ownership changed")
   221	    }
   222	    if restart {
   223	      restart_tunnel(saved, directory)
   224	      expires = @env.now() + 60000
   225	    }
   226	    if worker_alive(directory) {
   227	      wait_tunnel(directory, expires)
   228	      return
   229	    }
   230	    // A dead supervisor does not invalidate its still-live SSH transport.
   231	    // Reuse it so Devsy's old service cleanup cannot remove a new owner's helper.
   232	    let reusable = try {
   233	      check_tunnel(saved, directory)
   234	      true
   235	    } catch {
   236	      _ => false
   237	    }
   238	    if reusable {
   239	      for name in ["status.json", "git-status"] {
   240	        if @fs.exists(directory + "/" + name) {
   241	          @fs.remove(directory + "/" + name)
   242	        }
   243	      }
   244	      spawn_tunnel_worker(directory)
   245	      wait_tunnel(directory, expires)
   246	      return
   247	    }
   248	    stop_tunnel_master(saved, directory)
   249	  } else if restart {
   250	    restart_tunnel(state, directory)
   251	    expires = @env.now() + 60000
   252	  }
   253	  let socket_directory = @fs.tmpdir(prefix="oe")
   254	  let saved = Json::empty_object()
   255	  for
   256	    name in [
   257	      "workspaceId", "workspaceUid", "user", "command", "devsyEnv", "home", "context",
   258	      "connection", "projectRoot",
   259	    ] {
   260	    if field(state, name) is Some(value) {
   261	      set_field(saved, name, value)
   262	    }
   263	  }
   264	  set_field(saved, "socketDirectory", Json::string(socket_directory))
   265	  if port is Some(value) {
   266	    set_field(saved, "localPort", Json::number(value.to_double()))
   267	  }
   268	  @fs.write_file(directory + "/state.tmp", saved.stringify(), permission=0o600)
   269	  @fs.rename(directory + "/state.tmp", directory + "/state.json", replace=true)
   270	  @fs.write_file(directory + "/enabled", "", permission=0o600)
   271	  if @fs.exists(directory + "/status.json") {
   272	    @fs.remove(directory + "/status.json")
   273	  }
   274	  spawn_tunnel_worker(directory)
   275	  wait_tunnel(directory, expires)
   276	}
