   278	///|
   279	async fn restart_tunnel(state : Json, directory : String) -> Unit {
   280	  let enabled = directory + "/enabled"
   281	  let was_enabled = @fs.exists(enabled)
   282	  errdefer (if was_enabled && @fs.exists(directory) {
   283	    @fs.write_file(enabled, "", permission=0o600) catch {
   284	      _ => ()
   285	    }
   286	  })
   287	  let mut phase = if worker_alive(directory) { "worker" } else { "master" }
   288	  save_diagnostic(
   289	    "ssh-tunnel-restart",
   290	    "started",
   291	    phase~,
   292	    tunnel_directory=directory,
   293	  )
   294	  let mut timed_out = false
   295	  errdefer save_diagnostic(
   296	    "ssh-tunnel-restart",
   297	    if timed_out {
   298	      "timeout"
   299	    } else {
   300	      "failed"
   301	    },
   302	    phase~,
   303	    error_type=if timed_out { "shutdown_timeout" } else { "shutdown_failed" },
   304	    tunnel_directory=directory,
   305	  )
   306	  try {
   307	    if @fs.exists(enabled) {
   308	      @fs.remove(enabled)
   309	    }
   310	    @async.with_timeout(15000, async fn() {
   311	      while worker_alive(directory) {
   312	        @async.sleep(100)
   313	      }
   314	    })
   315	    phase = "master"
   316	    save_diagnostic(
   317	      "ssh-tunnel-restart",
   318	      "stopping",
   319	      phase~,
   320	      tunnel_directory=directory,
   321	    )
   322	    stop_tunnel_master(state, directory, verify=true)
   323	  } catch {
   324	    @async.TimeoutError as error => {
   325	      timed_out = true
   326	      raise error
   327	    }
   328	    error => raise error
   329	  }
   330	  save_diagnostic("ssh-tunnel-restart", "success", tunnel_directory=directory)
   331	}
