   860	///|
   861	async fn lifecycle_state(mode : String) -> (Json, Json) {
   862	  let input = @stdio.stdin.read_all()
   863	  let payload = @json.parse(input.text())
   864	  guard field(payload, "schemaVersion") == Some(Json::number(1)) else {
   865	    raise AdapterError("Invalid lifecycle payload schema")
   866	  }
   867	  let result = match field(payload, "recipeResult") {
   868	    Some(value) => value
   869	    None => raise AdapterError("Missing recipeResult")
   870	  }
   871	  let state = match field(result, "userData") {
   872	    Some(value) => value
   873	    None => raise AdapterError("Missing saved adapter state")
   874	  }
   875	  guard field(state, "adapterVersion") == Some(Json::number(1)) else {
   876	    raise AdapterError("Unsupported adapter state")
   877	  }
   878	  validate_state(state)
   879	  match workspace(state) {
   880	    Some(current) if field(current, "uid") == field(state, "workspaceUid") => ()
   881	    None if mode == "destroy" => ()
   882	    _ => raise AdapterError("Workspace missing or replaced")
   883	  }
   884	  (state, result)
   885	}
