   889	  state : Json,
   890	  install : Bool,
   891	  existing? : Json,
   892	  deadline? : UInt64,
   893	) -> Unit {
   894	  let connection = if required(state, "connection") == "ssh" {
   895	    ensure_ssh_worker(state, None, deadline?)
