   897	      "label": "Devsy",
   898	      "host": required(state, "workspaceId") + ".devsy",
   899	      "port": 22,
   900	      "username": required(state, "user"),
   901	      "proxyCommand": proxy(state, saved_proxy_executable(), services=false),
   902	    }
   903	    let output : Json = {
   904	      "type": "ssh",
   905	      "projectRoot": required(state, "projectRoot"),
   906	      "target": target,
   907	    }
   908	    output
   909	  } else if existing is Some(result) {
   910	    let port = match field(state, "localPort") {
   911	      Some(Json::Number(port, ..)) => port.to_int()
   912	      _ => raise AdapterError("Missing saved tunnel port")
   913	    }
   914	    ensure_ssh_worker(state, Some(port), deadline?)
   915	    match field(result, "connection") {
   916	      Some(value) => value
   917	      None => raise AdapterError("Missing saved connection")
