   943	///|
   944	async fn execute_inner(mode : String) -> Unit {
   945	  notify(mode)
   946	  let started = @env.now()
   947	  let (state, previous, deadline) = if mode == "create" {
   948	    let (state, expires) = create_state()
   949	    (state, Json::null(), Some(expires))
   950	  } else {
   951	    let (state, previous) = if mode == "recover" || mode == "restart" {
   952	      connection_timeout(started + 60000, async fn() { lifecycle_state(mode) })
   953	    } else {
   954	      lifecycle_state(mode)
   955	    }
   956	    (
   957	      state,
   958	      previous,
   959	      if mode == "recover" || mode == "restart" {
   960	        Some(started + 60000)
   961	      } else {
   962	        None
   963	      },
   964	    )
   965	  }
   966	  let operation = if mode == "resume" || mode == "suspend" || mode == "destroy" {
   967	    Some(connection_operation_lock(state))
   968	  } else {
   969	    None
   970	  }
   971	  defer (if operation is Some(lock) { lock.close() })
   972	  if mode == "resume" {
   973	    guard workspace(state) is Some(current) &&
   974	      field(current, "uid") == field(state, "workspaceUid") else {
   975	      raise AdapterError("Workspace missing or replaced before resume")
   976	    }
   977	    unpause_tunnel(state)
   978	  }
   979	  match mode {
   980	    "create" => {
   981	      create_recording.phase = "connection"
   982	      errdefer discard_created_workspace(state)
   983	      connection_timeout(deadline.unwrap(), async fn() {
   984	        codex_addon(state)
   985	        emit_connection(state, true, deadline?)
   986	      })
   987	    }
   988	    "resume" => {
   989	      ignore(
   990	        devsy(
   991	          state,
   992	          [
   993	            "--result-format",
   994	            "json",
   995	            "workspace",
   996	            "up",
   997	            required(state, "workspaceId"),
   998	            "--ide-launch",
   999	            "skip",
  1000	          ],
  1001	          "workspace-resume",
  1002	        ),
  1003	      )
  1004	      let expires = @env.now() + 60000
  1005	      connection_timeout(expires, async fn() {
  1006	        let port = if required(state, "connection") == "orca-server" {
  1007	          Some(reserve_server_port(state))
  1008	        } else {
  1009	          None
  1010	        }
  1011	        ensure_ssh_worker(state, port, deadline=expires)
  1012	        codex_addon(state)
  1013	        if required(state, "connection") == "orca-server" {
  1014	          ignore(recover_server(state))
  1015	        }
  1016	        emit_connection(state, false, existing=previous, deadline=expires)
  1017	      })
  1018	    }
  1019	    "recover" | "restart" => {
  1020	      recover_connection(state, restart=mode == "restart", deadline?)
  1021	      let connection = field(previous, "connection").unwrap()
  1022	      write_connection(state, connection)
  1023	    }
  1024	    "suspend" => {
  1025	      pause_tunnel(state)
  1026	      defer unpause_tunnel(state)
  1027	      ignore(
  1028	        devsy(
  1029	          state,
  1030	          ["workspace", "stop", required(state, "workspaceId")],
  1031	          "workspace-stop",
  1032	        ),
  1033	      )
  1034	    }
  1035	    "destroy" => {
  1036	      pause_tunnel(state)
  1037	      errdefer unpause_tunnel(state)
  1038	      ignore(
  1039	        devsy(
  1040	          state,
  1041	          [
  1042	            "workspace",
  1043	            "delete",
  1044	            required(state, "workspaceId"),
  1045	            "--ignore-not-found",
  1046	          ],
  1047	          "workspace-delete",
  1048	        ),
  1049	      )
  1050	      close_tunnel(state)
  1051	    }
  1052	    _ => raise AdapterError("Unknown command")
  1053	  }
  1054	  save_diagnostic(mode, "success")
  1055	  progress_message(mode + ": done (" + progress_timing(progress_started) + ")")
  1056	}
